AD_COLUMN.DEFAULTVALUE:
@SQL=SELECT COALESCE(MAX(LINE),0)+10 AS DefaultValue FROM M_LC_COST
 WHERE (m_landedcost_id is not null and m_landedcost_id =@m_landedcost_id@) 
   or (m_landedcost_id is null and m_inout_id = @m_inout_id@)

AD_COLUMN.SQLLOGIC:
(coalesce((select case when sum(abs(ol.qtyordered)) = 0 or iscancelled = 'Y' or cancelledorder_id is not null then 0 else 
round(coalesce(sum(abs(ol.qtyreserved)), 0)/sum(abs(ol.qtyordered)) * 100, 0) end 
from c_orderline ol where ol.c_order_id=c_order_id and ol.c_order_discount_id is null),0))

(coalesce((select case when sum(abs(ol.qtyordered)) = 0 or iscancelled = 'Y' or cancelledorder_id is not null then 0 else 
round(coalesce(sum(abs(ol.qtydelivered)), 0)/sum(abs(ol.qtyordered)) * 100, 0) end 
from c_orderline ol where ol.c_order_id=c_order_id and ol.c_order_discount_id is null),0))

(coalesce((select case when sum(abs(ol.qtyordered)) = 0 or iscancelled = 'Y' or cancelledorder_id is not null then 0 else 
round(coalesce(sum(abs(ol.qtyinvoiced)), 0)/sum(abs(ol.qtyordered)) * 100, 0)  end 
from c_orderline ol   where ol.c_order_id=c_order_id and  ol.c_order_discount_id is null), 0))
